t = int(input())
for i in range(t):
	(cans, minutes, outsidet, le, ri) = map(int, input().split())
	ans = -1
	for i in range(cans):
		(x, y) = map(int, input().split())
		for i in range(minutes):
			if x > outsidet + 1:
				x = x - 1
			elif x < outsidet - 1:
				x = x + 1
			else:
				x = outsidet
		if x >= le and x <= ri:
			if ans == -1:
				ans = y
			elif ans > y:
				ans = y
	print(ans)
